<h2>Estimate video file size from bitrate</h2><p class="lead">Convert video and audio bitrate plus duration into an approximate file size.</p><div class="notice">Use average bitrate for VBR footage. File size follows bitrate and time; resolution and codec matter only through the bitrate they produce.</div><div class="form-grid"><div class="field"><label for="video">Video bitrate (Mbps)</label><input id="video" type="number" value="20" min="0" step="any"></div><div class="field"><label for="audio">Audio bitrate (kbps)</label><input id="audio" type="number" value="192" min="0" step="any"></div><div class="field"><label for="minutes">Duration (minutes)</label><input id="minutes" type="number" value="10" min="0.001" step="any"></div></div><div class="tool-actions"><button class="btn btn-primary" id="calc" type="button">Calculate</button><button class="btn btn-secondary" id="reset" type="button">Reset</button></div><div class="result-box"><div class="result-grid"><div class="metric"><span>Total bitrate</span><strong id="total">—</strong></div><div class="metric"><span>Approximate file size</span><strong id="size">—</strong></div><div class="metric"><span>Storage per minute</span><strong id="permin">—</strong></div><div class="metric"><span>Binary size (GiB)</span><strong id="gib">—</strong></div></div><div id="note" class="helper" style="margin-top:12px"></div></div><script>
(()=>{
const $=id=>document.getElementById(id); const num=id=>Number($(id).value); const fmt=(v,d=2)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'—';
const defaults={}; document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>defaults[el.id]=el.value);
function clear(){$('total').textContent='—';$('size').textContent='—';$('permin').textContent='—';$('gib').textContent='—'; const n=$('note'); if(n){n.textContent='';n.className='helper';}}
function calculate(){try{const v=num('video'),a=num('audio'),m=num('minutes');if(!(v>=0&&a>=0&&m>0&&(v>0||a>0)))throw 0;const mbps=v+a/1000,bytes=mbps*1e6*(m*60)/8,gb=bytes/1e9,gib=bytes/1073741824;$('total').textContent=fmt(mbps,3)+' Mbps';$('size').textContent=fmt(gb,3)+' GB';$('permin').textContent=fmt(gb/m*1000,1)+' MB/min';$('gib').textContent=fmt(gib,3)+' GiB';$('note').textContent='This is a bitrate-based estimate. Containers, metadata, VBR peaks and codec muxing overhead can make real files slightly different.';}catch(e){clear(); const n=$('note'); if(n){n.textContent='Please check the inputs and try again.';n.className='helper danger';}}}
const c=$('calc'); if(c)c.addEventListener('click',calculate); const r=$('reset'); if(r)r.addEventListener('click',()=>{Object.entries(defaults).forEach(([id,v])=>{if($(id))$(id).value=v});calculate();});
document.querySelectorAll('.tool-panel input,.tool-panel select,.tool-panel textarea').forEach(el=>el.addEventListener('input',calculate));
calculate();
})();
</script>
